import SwiftUI
import WidgetKit

/// Picks the pre-rendered moon frame (`Moon.xcassets`, generated by `Tools/MoonRender`) for a phase.
enum MoonFrame {
    /// Sun–Moon elongation in degrees (0 new, 90 first quarter, 180 full, 270 last quarter) from the
    /// illuminated fraction k = (1 − cos E) / 2.
    static func elongation(illumination: Double, isWaxing: Bool) -> Double {
        let e = acos(1 - 2 * min(max(illumination, 0), 1)) * 180 / .pi
        return isWaxing ? e : 360 - e
    }

    /// Asset name of the nearest frame, e.g. "moon-090"; 360° wraps to "moon-000".
    static func name(illumination: Double, isWaxing: Bool, step: Int = 5) -> String {
        let e = elongation(illumination: illumination, isWaxing: isWaxing)
        let frame = Int((e / Double(step)).rounded()) * step % 360
        return String(format: "moon-%03d", frame)
    }

    /// Bundle holding `Moon.xcassets`: the widget extension itself, or, from the app, its embedded widget extension
    /// (the frames ship once, in the extension, to keep the app small).
    static let bundle: Bundle = {
        if Bundle.main.image(forResource: "moon-000") != nil { return Bundle.main }
        let appex = Bundle.main.builtInPlugInsURL?.appendingPathComponent("LuneWidget.appex")
        return appex.flatMap(Bundle.init(url:)) ?? Bundle.main
    }()

    /// Frames are rendered for the northern hemisphere (lit on the right when waxing); turned over in the south.
    static func rotation(latitude: Double) -> Angle {
        .degrees(latitude >= 0 ? 0 : 180)
    }
}

struct MoonView: View {
    let illumination: Double
    let isWaxing: Bool
    let latitude: Double
    /// Accented/vibrant modes show the frame desaturated so the system can tint it.
    var fullColor = true

    var body: some View {
        frame
            .aspectRatio(1, contentMode: .fit)
            .rotationEffect(MoonFrame.rotation(latitude: latitude))
            .accessibilityHidden(true)
    }

    @ViewBuilder private var frame: some View {
        let image = Image(MoonFrame.name(illumination: illumination, isWaxing: isWaxing), bundle: MoonFrame.bundle)
            .resizable()
        if !fullColor, #available(macOS 15.0, *) {
            image.widgetAccentedRenderingMode(.desaturated)
        } else {
            image
        }
    }
}
